```c
int nums_in_halves(char* str, int* num1, int* num2)
{
    int len = strlen(str), i;
    *num1 = *num2 = 0;
    for (i = 0; i < len / 2; i++)
        if ( islower(str[i]) )
            (*num1)++;
    for (i = (len + 1) / 2; str[i] != '\0'; i++)
        if ( isupper(str[i]) )
            (*num2)++;
    if (len % 2 == 0)
        return 0;
    if ( isdigit(str[len / 2]) )
        return 1;
    return -1;
}
```

```c
typedef struct
{
    int i, j;
} pair;

pair* indirect_friends(int** M, int size, int* new_size)
{
    int i, j, k, count = 0;
    pair* arr;
    *new_size = (size * size - size) / 2; //upper bound of possible number of pairs
    arr = (pair*)calloc(*new_size, sizeof(pair));
    for (i = 0; i < size; i++)
        for (j = 0; j < i; j++)
            if (M[i][j] == 0)
                for (k = 0; k < size; k++)
                    if (M[i][k] == 1 && M[k][j] == 1)
                    {
                        arr[count].i = i;
                        arr[count++].j = j;
                        break; //search for common friends of i and j has been terminated
                    }
    *new_size = count;
    arr = (pair*)realloc(arr, *new_size * sizeof(pair));
    return arr;
}
```

**הערה:** כשאין זוגות (`count == 0`) הקריאה `realloc(arr, 0)` מתנהגת בצורה שהתקן אינו מבטיח: היא עשויה להחזיר `NULL` או מצביע תקף (ב-C23 ההתנהגות לא מוגדרת). הפתרון הרשמי מניח ש-`NULL` מוחזר, כפי שקורה ב-glibc וב-clang/MSVC; במימוש אחר כדאי לטפל במקרה `count == 0` במפורש (`free(arr); return NULL;`).

